    var authorName=cu.name||cu.user_metadata?.full_name||(cu.email||'').split('@')[0]||'User';
    var newC={id:Date.now()+'',author_id:cu.id,author_name:authorName,text:text.trim(),created_at:new Date().toISOString()};
