  function editTemplate(t){setTplName(t.name);setTplSubject(t.subject);setTplBody(t.body||'');setEditTplId(t.id);}

  function applyFormat(setter,getter,tag){
    var ta=document.getElementById('comms_body_'+activeTab);
    if(!ta)return;
    var start=ta.selectionStart,end=ta.selectionEnd,val=getter;
    var sel=val.substring(start,end);
    var wrap='';
    if(tag==='bold')wrap='**'+sel+'**';
    else if(tag==='italic')wrap='_'+sel+'_';
    else if(tag==='underline')wrap='<u>'+sel+'</u>';
    else if(tag==='bullet')wrap='\n• '+sel;
    else if(tag==='link')wrap='['+sel+'](url)';
    else if(tag==='heading')wrap='\n### '+sel;
    var nv=val.substring(0,start)+wrap+val.substring(end);
    setter(nv);
    setTimeout(function(){ta.focus();ta.selectionStart=start;ta.selectionEnd=start+wrap.length;},50);
  }

  function FormatBar({bodyId,setter,getter}){
    var BT={background:'var(--tf-surface)',border:'1px solid var(--tf-border)',borderRadius:5,padding:'4px 8px',cursor:'pointer',fontSize:12,color:'var(--tf-text)',fontFamily:'inherit',lineHeight:1};
    return<div style={{display:'flex',gap:4,marginBottom:6,flexWrap:'wrap'}}>
      <button type="button" onClick={function(){applyFormat(setter,getter,'bold');}} style={Object.assign({},BT,{fontWeight:800})} title="Bold">B</button>
      <button type="button" onClick={function(){applyFormat(setter,getter,'italic');}} style={Object.assign({},BT,{fontStyle:'italic'})} title="Italic">I</button>
      <button type="button" onClick={function(){applyFormat(setter,getter,'underline');}} style={Object.assign({},BT,{textDecoration:'underline'})} title="Underline">U</button>
      <button type="button" onClick={function(){applyFormat(setter,getter,'heading');}} style={BT} title="Heading">H</button>
      <button type="button" onClick={function(){applyFormat(setter,getter,'bullet');}} style={BT} title="Bullet">•</button>
      <button type="button" onClick={function(){applyFormat(setter,getter,'link');}} style={BT} title="Link">🔗</button>
    </div>;
  }

  async function logComm(clientId,type,subject,body,toEmail,cc,threadId){
    var row={org_id:org.id,client_id:clientId||null,type:type||'email_sent',subject:subject||'',body:body||'',to_email:toEmail||'',cc:cc||'',thread_id:threadId||null,created_by:cu.id};
    var res=await supabase.from('comm_logs').insert(row).select().single();
    if(res.data)setCommLogs(function(p){return[res.data].concat(p);});
    return res.data;
  }

  function sendBulk(){
    var selCount=Object.keys(bulkSelIds).length;
    if(selCount===0){showToast('Select at least one client','err');return;}
    if(!bulkSubject.trim()){showToast('Subject required','err');return;}
    var emails=[];
    var cids=Object.keys(bulkSelIds);
    cids.forEach(function(cid){var c=emailClients.find(function(x){return x.id===cid;});if(c&&c.email&&emails.indexOf(c.email)===-1)emails.push(c.email);});
    if(emails.length===0){showToast('No emails found for selected clients','err');return;}
    var mailto='mailto:?bcc='+encodeURIComponent(emails.join(','));
    if(bulkCC.trim())mailto+='&cc='+encodeURIComponent(bulkCC.trim());
    mailto+='&subject='+encodeURIComponent(bulkSubject)+'&body='+encodeURIComponent(bulkBody);
    window.open(mailto,'_blank');
    cids.forEach(function(cid){var c=emailClients.find(function(x){return x.id===cid;});if(c&&c.email)logComm(cid,'email_sent',bulkSubject,bulkBody,c.email,bulkCC);});
    showToast('Email client opened for '+emails.length+' recipient'+(emails.length!==1?'s':''));
  }

  // ── Client reminders ──────────────────────────────────────────────────
  async function loadReminderWork(){
    setRemLoading(true);
    try{
      var todayStr=new Date().toISOString().slice(0,10);
      var maxStr=new Date(Date.now()+(Number(remDays)||7)*86400000).toISOString().slice(0,10);
      var rw=await supabase.from('worksheets').select('id,work_type,period_label').eq('org_id',org.id).limit(4000);
      var wsMap={};(rw.data||[]).forEach(function(w){wsMap[w.id]=w;});
      var rr=await supabase.from('worksheet_rows').select('id,worksheet_id,client_id,due_date,status').eq('org_id',org.id).neq('status','completed').not('due_date','is',null).lte('due_date',maxStr).limit(6000);
      var byClient={};
      (rr.data||[]).forEach(function(r){
        var ws=wsMap[r.worksheet_id];if(!ws)return;
        var c=emailClients.find(function(x){return x.id===r.client_id;});
        if(!c||!c.email)return;
        var e=byClient[r.client_id]||(byClient[r.client_id]={client:c,items:[]});
        e.items.push({row_id:r.id,work_type:ws.work_type,period:ws.period_label,due_date:r.due_date,overdue:r.due_date<todayStr});
      });
      var list=Object.keys(byClient).map(function(cid){var e=byClient[cid];e.items.sort(function(a,b){return (a.due_date||'').localeCompare(b.due_date||'');});e.overdueCount=e.items.filter(function(i){return i.overdue;}).length;return e;})
        .sort(function(a,b){return (b.overdueCount-a.overdueCount)||a.client.name.localeCompare(b.client.name);});
      setRemRows(list);
      var sel={};list.forEach(function(x){sel[x.client.id]=true;});setRemSel(sel);
      setRemLoaded(true);
    }catch(e){showToast('Failed to load due work','err');}
    setRemLoading(false);
  }
  function mergeRem(tpl,e){
    var c=e.client;
    var itemsText=e.items.map(function(it){return '• '+it.work_type+(it.period?' ('+it.period+')':'')+' — due '+it.due_date+(it.overdue?' — OVERDUE':'');}).join('\n');
    var first=e.items[0]||{};
    return String(tpl||'').replace(/\{client\}/g,c.display_name||c.name||'').replace(/\{firm\}/g,org.name||'').replace(/\{work_type\}/g,first.work_type||'').replace(/\{due_date\}/g,first.due_date||'').replace(/\{period\}/g,first.period||'').replace(/\{items\}/g,itemsText);
  }
  async function sendReminders(){
    if(!gmailToken){showToast('Connect Gmail (Gmail tab) to send from your firm address','err');return;}
    var sel=remRows.filter(function(x){return remSel[x.client.id];});
    if(!sel.length){showToast('Select at least one client','err');return;}
    if(!remSubject.trim()){showToast('Subject required','err');return;}
    setRemSending(true);setRemResult(null);var ok=0,fail=0;
    for(var i=0;i<sel.length;i++){
      var e=sel[i];var c=e.client;
      var subjM=mergeRem(remSubject,e);
      var plain=mergeRem(remBody,e);
      // buildMimeEmail sends text/html — convert newlines to <br> so paragraphs render.
      var htmlBody='<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1a2332;max-width:600px;">'+plain.replace(/\n/g,'<br>')+'</div>';
      try{
        var encoded=buildMimeEmail(c.email,subjM,htmlBody,'','','','','',[]);
        var res=await gmailApi('messages/send',null,{method:'POST',headers:{'Authorization':'Bearer '+gmailToken,'Content-Type':'application/json'},body:JSON.stringify({raw:encoded})});
        if(res&&res.id){ok++;logComm(c.id,'email_sent',subjM,plain,c.email,'');}else fail++;
      }catch(err){fail++;}
    }
    setRemSending(false);
    setRemResult({ok:ok,fail:fail});
    showToast('Sent '+ok+' reminder'+(ok!==1?'s':'')+(fail?' · '+fail+' failed':''),fail&&!ok?'err':'ok');
  }
  async function saveRemConfig(nextAuto){
    var auto=nextAuto===undefined?remAuto:nextAuto;
    var cfg={enabled:auto,days_before:Number(remDays)||7,subject:remSubject,body:remBody};
    setRemAuto(auto);
    var res=await supabase.from('organizations').update({client_reminder_config:cfg}).eq('id',org.id);
    if(!res.error){if(org)org.client_reminder_config=cfg;showToast(auto?'Auto-reminders ON · settings saved':'Settings saved');}
    else showToast('Save failed','err');
  }

  function sendSingle(threadId){
    var to=singleTo.trim()||'';
    if(!to&&singleClientId){var c=emailClients.find(function(x){return x.id===singleClientId;});if(c)to=c.email||'';}
    if(!to){showToast('Enter recipient email','err');return;}
    if(!singleSubject.trim()){showToast('Subject required','err');return;}
    var mailto='mailto:'+encodeURIComponent(to);
    var params=[];
    if(singleCC.trim())params.push('cc='+encodeURIComponent(singleCC.trim()));
    params.push('subject='+encodeURIComponent(singleSubject));
    params.push('body='+encodeURIComponent(singleBody));
    mailto+='?'+params.join('&');
    window.open(mailto,'_blank');
    logComm(singleClientId||null,'email_sent',singleSubject,singleBody,to,singleCC,threadId||null);
    showToast('Email client opened');
  }

